protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9 renamed the discriminator property from "Discriminator" to "$type".
        // Preserve the old name so existing 500K documents remain readable and
        // direct SQL queries that reference c.Discriminator keep working.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9 changed the default id format from "EntityName|<key>" to just "<key>".
        // Use IdProperty() to keep the legacy "Product|<key>" format so existing
        // documents are still addressable without a data migration.
        entity.Property(p => p.Id).ToJsonPropertyName("id");
        entity.HasPartitionKey(p => p.Id);
    });

    // EF Core 9 Cosmos provider throws for HasIndex — Cosmos uses indexing policies
    // defined at the container level, not EF-managed indexes.
    // The previous HasIndex(p => p.Sku) call has been removed.
}

